INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102655,0,0,'Over here! I think you will approve of the changes we\'ve made!',14,0,100.0,0,0,0,105027,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102655,1,0,'I\'d like to introduce you to Calia Menethil... yes, that Menethil. She has been a great help these past few years. I\'d like her to assist you, helping the helpless, conveying your word to the world, all that.',12,0,100.0,0,0,0,105153,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102655,2,0,'A fine start! The Kirin Tor have given us a permanent portal to Dalaran, as well as one that will bring you from the city back to Netherlight. Good luck!',12,0,100.0,0,0,0,106260,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102693,0,0,'The ritual is interrupted and a dark energy amasses!',41,0,100.0,0,0,0,105085,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102693,1,0,'Eliminate... all... life...',12,0,100.0,0,0,0,105084,0,'LegionCore');
