INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110564,1,0,'In times such as these, we cannot afford to turn away those willing to help. We welcome you, as our new ally.',12,0,100.0,1,0,68275,119549,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110564,2,0,'Another shadow priest spouting nonsense. I can\'t say I\'m surprised. Things like this are bound to happen when you linger too close to the void.',12,0,100.0,1,0,68302,118800,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110564,3,0,'We will fight and win many more battles under your leadership, High Priest.',12,0,100.0,1,0,69384,120506,0,'LegionCore');
