INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110691,0,0,'They\'re taunting us, you know. The shadows. They see our demise.',12,0,100.0,1,0,68289,118807,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110691,1,0,'You don\'t hear them, do you? Their laughing... their warning. Our time is coming.',12,0,100.0,1,0,68290,118814,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110691,2,0,'The void sends whispers of our fate, a gruesome death! Light a candle for your loved ones, priest, because the end is near and inescapable.',12,0,100.0,1,0,68291,118815,0,'LegionCore');
