INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (118528,0,0,'Chin up, Roland. It appears help has arrived.',12,0,100.0,1,0,82563,127092,0,'LegionCore');
